 * Process-wide notification hub for source-file changes.
 *
 * The change-detection adapter reports raw file-system events; this module lets any number of
 * server-side consumers (e.g. the review addon, which invalidates a cached review when the
 * files it describes change) subscribe to those events without coupling to the detector's
 * internals. It is intentionally a module-level singleton: the dev server is long-lived and a
 * single set of listeners survives across reconnecting browser tabs.
 */
import type { FileChangeEvent } from './adapters/index.ts';

export type SourceFileChangeListener = (event: FileChangeEvent) => void;

const listeners = new Set<SourceFileChangeListener>();

/**
 * Register a listener for source-file changes.
 *
 * @returns an unsubscribe function that removes the listener; calling it more than once is safe.
 */
export function subscribeToSourceFileChanges(listener: SourceFileChangeListener): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

/**
 * Deliver a change event to every registered listener. Listeners are invoked from a snapshot so
 * subscribing/unsubscribing during delivery does not perturb the current dispatch, and a throwing
 * listener neither prevents the others from running nor propagates out of the notifier.
 */
export function notifySourceFileChange(event: FileChangeEvent): void {
  for (const listener of [...listeners]) {
    try {
      listener(event);
    } catch {
      // A misbehaving listener must not break the notification for the others.
    }
  }
}

/** Test-only: drop all listeners so no events are delivered after a reset. */
export function internal_resetSourceFileChangeListeners(): void {
  listeners.clear();
}
