    cached = enriched;
    channel.emit(EVENTS.DISPLAY_REVIEW, enriched);
  });

  channel.on(EVENTS.REQUEST_REVIEW, () => {
    if (cached) {
      // `cached` already carries `stale: true` once outdated, so a late/refreshed tab picks up
      // the staleness through this replay.
      channel.emit(EVENTS.DISPLAY_REVIEW, cached);
    }
  });

  // Invalidate the cached review when its source files change after the grace window. Emitted
  // once per review so open tabs can flag the current overlay as outdated.
  subscribeToSourceFileChanges(() => {
    if (!cached || cached.stale || cached.createdAt === undefined) {
      return;
    }
    if (Date.now() - cached.createdAt <= STALE_GRACE_WINDOW_MS) {
      return;
    }
    cached = { ...cached, stale: true };
    channel.emit(EVENTS.REVIEW_STALE);
  });

  return channel;
};

